fn main() {
    let message = "hello swift world";
    println!("{}", message);
    let sum = compute(1, 2, 3);
    println!("sum = {}", sum);
    log_result(sum);
}

fn compute(a: i32, b: i32, c: i32) -> i32 {
    a + b + c
}

fn log_result(value: i32) {
    eprintln!("result: {}", value);
}
